package dev.aster.charts;

import android.content.Context;
import android.os.Looper;
import android.os.Handler;
import android.os.SystemClock;
import org.json.*;
import java.util.function.Consumer;
import java.util.*;

/** Owner-thread callback tests. Root's runner executes this in the Android app. */
final class AsyncVerification {
    private final JSONArray checks=new JSONArray(),jobs=new JSONArray(),geometryKeyDiagnostics=new JSONArray(),byteParityCases=new JSONArray();
    private Context context;private AsterEngine source;private Consumer<JSONObject> completion;private Large large;
    private String before,expected;private JSONObject event,mismatch;private boolean finished=false;private int byteCase;private AsterEngine byteReference;
    private final Handler heartbeat=new Handler(Looper.getMainLooper());private long lastBeat,maxBeatDelay;private int beats;
    private final Runnable pulse=new Runnable(){@Override public void run(){long now=SystemClock.uptimeMillis();if(lastBeat!=0)maxBeatDelay=Math.max(maxBeatDelay,now-lastBeat);lastBeat=now;beats++;if(!finished)heartbeat.postDelayed(this,16);}};
    private void check(boolean value,String reason){if(!value)throw new AssertionError(reason);checks.put(reason);}
    private String probe(AsterEngine e) throws JSONException {
        JSONObject state=(JSONObject)e.command("inspect"),outputs=new JSONObject();JSONArray series=state.getJSONArray("series");
        for(int i=0;i<series.length();i++){JSONObject item=series.getJSONObject(i);if(!item.has("indicator")||item.isNull("indicator"))continue;String id=item.getString("indicator"),output=item.optString("output","value");outputs.put(id+":"+output,e.command("indicatorValues",id,output));}
        JSONObject layout=e.scene(1200,700).getJSONObject("layout");normalizeGeometryKey(layout,geometryKeyDiagnostics);
        return canonical(new JSONObject().put("state",state).put("outputs",outputs).put("layout",layout).put("saved",new JSONObject(e.saveDrawings())));
    }
    // A source store and prepared store belong to different QuickJS contexts.
    // Cache identity may change; dimensions/view/timeVersion/panel geometry must
    // remain identical. Keep original keys in diagnostics and normalize only ID.
    static void normalizeGeometryKey(JSONObject layout,JSONArray diagnostics) throws JSONException {
        String original=layout.getString("geometryKey");JSONArray key=new JSONArray(original);if(key.length()<7||!(key.get(4) instanceof Number)||!(key.get(5) instanceof Number))throw new AssertionError("Geometry key framing");
        double identity=key.getDouble(4),timeVersion=key.getDouble(5);if(!Double.isFinite(identity)||identity<=0||identity!=Math.rint(identity)||identity>9007199254740991d)throw new AssertionError("Positive integer geometry store identity");
        if(!Double.isFinite(timeVersion)||timeVersion<0||timeVersion!=Math.rint(timeVersion)||timeVersion>9007199254740991d)throw new AssertionError("Geometry time version integer");
        if(diagnostics!=null)diagnostics.put(new JSONObject().put("geometryKey",original).put("storeIdentity",key.get(4)));key.put(4,"per-context");layout.put("geometryKey",key.toString());
    }
    private String canonical(Object value) throws JSONException {if(value instanceof JSONObject){JSONObject object=(JSONObject)value;ArrayList<String> keys=new ArrayList<>();Iterator<String> iterator=object.keys();while(iterator.hasNext())keys.add(iterator.next());Collections.sort(keys);StringBuilder text=new StringBuilder("{");for(String key:keys){if(text.length()>1)text.append(',');text.append(JSONObject.quote(key)).append(':').append(canonical(object.get(key)));}return text.append('}').toString();}if(value instanceof JSONArray){JSONArray array=(JSONArray)value;StringBuilder text=new StringBuilder("[");for(int i=0;i<array.length();i++){if(i>0)text.append(',');text.append(canonical(array.get(i)));}return text.append(']').toString();}return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
    private boolean sameProbe(String actual,String expected) throws JSONException {if(actual.equals(expected))return true;mismatch=new JSONObject().put("expected",new JSONObject(expected)).put("actual",new JSONObject(actual));return false;}
    private void verifyGeometryComparison() throws JSONException {
        String original="[1200,700,200,480,2,3,[\"price\",12,1118,12,500.5,90,110,\"linear\",false,null]]";
        JSONObject expected=new JSONObject().put("geometryKey",original),other=new JSONObject().put("geometryKey",original.replace("480,2,3","480,1,3"));normalizeGeometryKey(expected,null);normalizeGeometryKey(other,null);check(canonical(expected).equals(canonical(other)),"Context-local geometry identities normalized after validation");
        JSONObject changed=new JSONObject().put("geometryKey",original.replace("480,2,3","480,2,4"));normalizeGeometryKey(changed,null);check(!canonical(expected).equals(canonical(changed)),"Geometry time version differences remain observable");
        changed=new JSONObject().put("geometryKey",original.replace("90,110","91,110"));normalizeGeometryKey(changed,null);check(!canonical(expected).equals(canonical(changed)),"Geometry panel range differences remain observable");
        boolean invalid=false;try{normalizeGeometryKey(new JSONObject().put("geometryKey",original.replace("480,2,3","480,0,3")),null);}catch(AssertionError error){invalid=true;}check(invalid,"Geometry identity must be positive");
        invalid=false;try{normalizeGeometryKey(new JSONObject().put("geometryKey",original.replace("480,2,3","480,2.5,3")),null);}catch(AssertionError error){invalid=true;}check(invalid,"Geometry identity must be an integer");
    }
    private void configure(AsterEngine e) throws JSONException {
        e.invoke("nativeInit",512);JSONArray rows=new JSONArray();for(int i=0;i<512;i++){double p=100+Math.sin(i*0.07)*4+i*0.01;rows.put(new JSONObject().put("time",1700000000000L+i*60000L).put("open",p).put("high",p+2).put("low",p-2).put("close",p+Math.cos(i*0.03)).put("volume",1000+i));}e.setData(rows);
        for(String name:new String[]{"rsi","macd","bollinger","atr","adx","stochastic","obv"})e.invoke("nativeIndicator",name,name,new JSONObject(),"price");
        String id=e.addDrawing(new JSONObject().put("type","trendline").put("points",new JSONArray().put(new JSONObject().put("time",1700000000000L).put("price",101)).put(new JSONObject().put("time",1700000600000L).put("price",102))));
        e.editDrawing(id,new JSONObject().put("text","saved history 🚀"));e.selectDrawing(id);e.invoke("nativeView",200,480);e.scene(1200,700);
    }
    private JSONObject correction(AsterEngine e) throws JSONException {
        JSONObject bar=new JSONObject(((JSONObject)e.command("inspect")).getJSONObject("lastBar").toString());
        bar.put("close",bar.getDouble("close")+0.25).put("high",Math.max(bar.getDouble("high"),bar.getDouble("close")));
        return new JSONObject().put("kind","correction").put("bar",bar);
    }
    private AsterEngine.AsyncListener listener(Consumer<AsterEngine.AsyncResult> done){return new AsterEngine.AsyncListener(){
        @Override public void onProgress(AsterEngine.AsyncProgress progress){if(Looper.myLooper()!=Looper.getMainLooper())throw new AssertionError("progress owner");}
        @Override public void onComplete(AsterEngine.AsyncResult result){try{check(Looper.myLooper()==Looper.getMainLooper(),"terminal callback on UI owner");jobs.put(result.toJSON());done.accept(result);}catch(Throwable error){finish(error);}}
    };}
    private void finish(Throwable error){if(finished)return;finished=true;heartbeat.removeCallbacks(pulse);if(byteReference!=null){byteReference.close();byteReference=null;}try{JSONObject report=new JSONObject().put("passed",error==null?checks.length():0).put("checks",checks).put("jobs",jobs).put("fullByteParity",byteParityCases).put("ownerHeartbeatCount",beats).put("ownerHeartbeatMaxIntervalMs",maxBeatDelay).put("heartbeatScope","512-bar correctness/lifecycle fixture, not the 1m performance fixture").put("geometryKeyComparison","Only positive integer per-context store identity at index 4 normalized; timeVersion at index 5 and all other geometry/layout/vector/UI fields compared exactly").put("originalGeometryKeys",geometryKeyDiagnostics).put("physicalDevice",false);if(error!=null)report.put("failed",true).put("error",error.toString());if(mismatch!=null)report.put("probeMismatch",mismatch);completion.accept(report);}catch(JSONException errorJSON){throw new RuntimeException(errorJSON);}}
    void runLarge(Context context,AsterEngine engine,int count,Consumer<JSONObject> completion){large=new Large(context,engine,count,completion);large.run();}
    void cancel(){if(large!=null)large.finish(new IllegalStateException("Large verification activity destroyed"));}
    void run(Context context,AsterEngine engine,Consumer<JSONObject> completion){this.context=context;source=engine;this.completion=completion;try{
        verifyGeometryComparison();heartbeat.post(pulse);configure(source);event=correction(source);
        AsterEngine expectedEngine=new AsterEngine(context,512);
        try{configure(expectedEngine);expectedEngine.applyDataEvent(event);expectedEngine.setTheme(new JSONObject().put("background","#172535"));expected=probe(expectedEngine);}finally{expectedEngine.close();}
        source.applyDataEventAsync(event,listener(result->{try{
            check(result.succeeded(),"isolated computation success");source.scene(1200,700);check(sameProbe(probe(source),expected),"async exact vectors/range/view/drawing/UI merge against synchronous result");String saved=source.saveDrawings();source.undo();check(!source.saveDrawings().equals(saved),"async preserves undo history");source.redo();check(source.saveDrawings().equals(saved),"async preserves redo history");
            testFullBytes();
        }catch(Throwable error){finish(error);}}));source.setTheme(new JSONObject().put("background","#172535"));
    }catch(Throwable error){finish(error);}}
    private void testFullBytes() throws Exception {if(byteCase==3){testCancel();return;}configure(source);byteReference=new AsterEngine(context,512);configure(byteReference);int index=new int[]{0,256,511}[byteCase];JSONObject event=(JSONObject)source.invoke("nativeBenchmarkEvent",index);byteReference.applyDataEvent(event);byteReference.scene(1200,700);source.applyDataEventAsync(event,listener(result->{try{check(result.succeeded(),"full-byte correction succeeds at index "+index);source.scene(1200,700);JSONObject state=(JSONObject)source.command("inspect");JSONArray series=state.getJSONArray("series");HashSet<String> compared=new HashSet<>(),indicatorIDs=new HashSet<>();long bytes=0;for(int i=0;i<series.length();i++){JSONObject item=series.getJSONObject(i);if(!item.has("indicator")||item.isNull("indicator"))continue;String id=item.getString("indicator"),output=item.optString("output","value"),key=id+":"+output;if(!compared.add(key))continue;indicatorIDs.add(id);byte[] actual=source.indicatorBytes(id,output,0,512),expected=byteReference.indicatorBytes(id,output,0,512);if(!Arrays.equals(actual,expected))throw new AssertionError("Float64 bytes differ "+key+" correction index "+index);bytes+=actual.length;}check(indicatorIDs.size()==8&&compared.size()==15,"eight indicators and all15 full Float64 vectors match at index "+index);check(sameProbe(probe(source),probe(byteReference)),"Full-byte case preserves exact structural UI/ranges");byteParityCases.put(new JSONObject().put("index",index).put("indicators",8).put("outputs",15).put("comparedBytes",bytes).put("scope","all512 logical Float64 values including NaN payload/signedzero, same QuickJS build; JSON probe separately covers UI/ranges/history"));byteReference.close();byteReference=null;byteCase++;testFullBytes();}catch(Throwable error){if(byteReference!=null){byteReference.close();byteReference=null;}finish(error);}}));}
    private void testCancel() throws JSONException {before=probe(source);AsterEngine.AsyncJob job=source.applyDataEventAsync(correction(source),listener(result->{try{
        check(result.status.equals("cancelled"),"cancel before capture terminal");check(sameProbe(probe(source),before),"cancel keeps source state");testStale();
    }catch(Throwable error){finish(error);}}));job.cancel();}
    private void testStale() throws JSONException {JSONObject change=correction(source);source.applyDataEventAsync(change,listener(result->{try{
        check(result.status.equals("stale"),"source mutation rejects stale snapshot");check(sameProbe(probe(source),before),"stale result does not overwrite newer source");testFailure();
    }catch(Throwable error){finish(error);}}));source.applyDataEvent(change);source.scene(1200,700);before=probe(source);}
    private void testFailure() throws JSONException {before=probe(source);JSONObject invalid=correction(source);invalid.getJSONObject("bar").put("high",-1);source.applyDataEventAsync(invalid,listener(result->{try{
        check(result.status.equals("failed"),"worker invalid event reports failure");check(sameProbe(probe(source),before),"failed event leaves source data and UI unchanged");testCancelDuring();
    }catch(Throwable error){finish(error);}}));}
    private void testCancelDuring() throws JSONException {before=probe(source);final AsterEngine.AsyncJob[] job={null};job[0]=source.applyDataEventAsync(correction(source),new AsterEngine.AsyncOptions(30000,1),new AsterEngine.AsyncListener(){
        @Override public void onProgress(AsterEngine.AsyncProgress value){if(value.phase.equals("calculate")&&job[0]!=null)job[0].cancel();}
        @Override public void onComplete(AsterEngine.AsyncResult result){try{jobs.put(result.toJSON());check(result.status.equals("cancelled"),"cancel during calculate chunk boundary");check(sameProbe(probe(source),before),"mid-computation cancel keeps original state");testReadyBackgroundCancel();}catch(Throwable error){finish(error);}}
    });}
    private void testReadyBackgroundCancel() throws JSONException {before=probe(source);final AsterEngine.AsyncJob[] job={null};final boolean[] accepted={false};job[0]=source.applyDataEventAsync(correction(source),new AsterEngine.AsyncListener(){
        @Override public void onProgress(AsterEngine.AsyncProgress value){if(!value.phase.equals("ready")||accepted[0])return;Thread cancellation=new Thread(()->{job[0].cancel();},"Aster verification ready cancellation");cancellation.start();try{cancellation.join(2000);check(!cancellation.isAlive(),"background cancel returned before owner context publication");accepted[0]=true;}catch(InterruptedException error){Thread.currentThread().interrupt();throw new IllegalStateException(error);}}
        @Override public void onComplete(AsterEngine.AsyncResult result){try{jobs.put(result.toJSON());check(accepted[0]&&result.status.equals("cancelled"),"ready phase background cancel wins before publication");check(sameProbe(probe(source),before),"ready cancellation preserves source vectors/view/drawings");testConfigStale();}catch(Throwable error){finish(error);}}
    });}
    private void testConfigStale() throws JSONException {source.applyDataEventAsync(correction(source),listener(result->{try{check(result.status.equals("stale"),"series binding mutation rejects stale job");check(sameProbe(probe(source),before),"config stale keeps newer configuration");source.removeSeries("async-stale-series");testInitStale();}catch(Throwable error){finish(error);}}));source.addSeries(new JSONObject().put("id","async-stale-series").put("type","line").put("panel","price").put("source","close"));before=probe(source);}
    private void testInitStale() throws JSONException {source.applyDataEventAsync(correction(source),listener(result->{try{check(result.status.equals("stale"),"nativeInit identity change rejects job");check(sameProbe(probe(source),before),"nativeInit replacement is retained");testTimeout();}catch(Throwable error){finish(error);}}));source.invoke("nativeInit",512);source.scene(1200,700);before=probe(source);}
    private void testTimeout() throws JSONException {before=probe(source);source.applyDataEventAsync(correction(source),new AsterEngine.AsyncOptions(1,1),listener(result->{try{check(result.status.equals("timedOut"),"job timeout before commit");check(sameProbe(probe(source),before),"timeout leaves original data unchanged");testSupersede();}catch(Throwable error){finish(error);}}));}
    private void testSupersede() throws JSONException {final boolean[] oldDone={false},newDone={false};final Runnable proceed=()->{if(oldDone[0]&&newDone[0])try{testWrongOwner();}catch(Throwable error){finish(error);}};
        source.applyDataEventAsync(correction(source),listener(result->{check(result.status.equals("superseded"),"new request supersedes previous job");oldDone[0]=true;proceed.run();}));
        source.applyDataEventAsync(correction(source),listener(result->{check(result.succeeded(),"replacement job succeeds exactly once");newDone[0]=true;proceed.run();}));
    }
    private void testWrongOwner() throws Exception {final boolean[] rejected={false};Thread wrong=new Thread(()->{try{source.applyDataEventAsync(new JSONObject(),listener(r->{}));}catch(IllegalStateException expected){rejected[0]=true;}catch(Exception other){}});wrong.start();wrong.join(2000);check(rejected[0],"async wrong owner rejected synchronously");testCallbackFailure();}
    private void testCallbackFailure() throws JSONException {source.applyDataEventAsync(correction(source),new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress ignored){throw new IllegalStateException("Expected verification callback failure");}@Override public void onComplete(AsterEngine.AsyncResult result){try{jobs.put(result.toJSON());check(result.succeeded(),"progress callback failure does not stop computation/cleanup");testClose();}catch(Throwable error){finish(error);}}});}
    private void testClose() throws Exception {AsterEngine closing=new AsterEngine(context,512);closing.applyDataEventAsync(correction(closing),listener(result->{try{
        check(result.status.equals("closed"),"source close terminates isolated job once");source.invoke("nativeInit",10000);finish(null);
    }catch(Throwable error){finish(error);}}));closing.close();}

    /** Full byte equality is separate from the measured benchmark and hashes. */
    private static final class Large {
        final Context context;final AsterEngine source;final int count;final Consumer<JSONObject> completion;
        final Handler handler=new Handler(Looper.getMainLooper());final JSONArray checks=new JSONArray(),jobs=new JSONArray(),cases=new JSONArray();
        final long started=System.nanoTime();AsterEngine reference;AsterEngine.AsyncJob active;boolean finished;int correctionCase,outputIndex,offset;long comparedBytes;JSONArray bindings;String before;JSONObject mismatch;
        Large(Context context,AsterEngine source,int count,Consumer<JSONObject> completion){this.context=context;this.source=source;this.count=count;this.completion=completion;}
        void check(boolean value,String reason){if(!value)throw new AssertionError(reason);checks.put(reason);}
        void run(){try{if(count<512||count>1048576)throw new IllegalArgumentException("Large verification supports512..1048576 bars");configure(source);reference=new AsterEngine(context,0,PrepareVerification.options());configure(reference);bindings=((JSONObject)source.command("inspect")).getJSONArray("series");HashSet<String> ids=new HashSet<>(),outputs=new HashSet<>();JSONArray unique=new JSONArray();for(int i=0;i<bindings.length();i++){JSONObject binding=bindings.getJSONObject(i);if(!binding.has("indicator")||binding.isNull("indicator"))continue;String id=binding.getString("indicator"),output=binding.optString("output","value");ids.add(id);if(outputs.add(id+":"+output))unique.put(new JSONObject().put("id",id).put("output",output));}bindings=unique;check(ids.size()==8&&bindings.length()==15,"Large fixture configures the same eight builtin names and15 outputs");nextCorrection();}catch(Throwable error){finish(error);}}
        void configure(AsterEngine engine)throws JSONException {engine.invoke("nativeInit",count,PrepareVerification.options());PrepareVerification.indicators(engine);String id=engine.addDrawing(new JSONObject().put("type","trendline").put("points",new JSONArray().put(new JSONObject().put("time",1700000000000L).put("price",100)).put(new JSONObject().put("time",1700000600000L).put("price",101))));engine.editDrawing(id,new JSONObject().put("text","large byte reference"));engine.selectDrawing(id);engine.scene(1200,700);}
        AsterEngine.AsyncListener listener(Consumer<AsterEngine.AsyncResult> callback){return new AsterEngine.AsyncListener(){@Override public void onComplete(AsterEngine.AsyncResult result){if(finished)return;try{check(Looper.myLooper()==Looper.getMainLooper(),"Large terminal callback on owner");jobs.put(result.toJSON());active=null;callback.accept(result);}catch(Throwable error){finish(error);}}};}
        JSONObject correction(int index)throws JSONException {return (JSONObject)source.invoke("nativeBenchmarkEvent",index);}
        String snapshot(AsterEngine engine)throws JSONException {JSONObject digest=new JSONObject((String)engine.invoke("nativeBenchmarkDigest"));normalizeGeometryKey(digest.getJSONObject("layout"),null);return PrepareVerification.canonical(new JSONObject().put("digest",digest).put("state",engine.command("inspect")).put("saved",new JSONObject(engine.saveDrawings())));}
        void same(String actual,String expected,String reason)throws JSONException {if(!actual.equals(expected)){mismatch=new JSONObject().put("actual",new JSONObject(actual)).put("expected",new JSONObject(expected));throw new AssertionError(reason);}checks.put(reason);}
        void nextCorrection()throws JSONException {if(correctionCase==3){before=snapshot(source);invalid();return;}int index=new int[]{0,count/2,count-1}[correctionCase];JSONObject event=correction(index);reference.applyDataEvent(event);reference.scene(1200,700);active=source.applyDataEventAsync(event,new AsterEngine.AsyncOptions(120000,4096),listener(result->{try{check(result.succeeded(),"Large correction succeeds at index "+index);source.scene(1200,700);outputIndex=0;offset=0;comparedBytes=0;handler.post(this::compareChunk);}catch(Throwable error){finish(error);}}));}
        void compareChunk(){if(finished)return;try{if(outputIndex==bindings.length()){int index=new int[]{0,count/2,count-1}[correctionCase];same(snapshot(source),snapshot(reference),"Large correction exact layout/UI/raw-tail and diagnostic digest at index "+index);cases.put(new JSONObject().put("index",index).put("logicalValuesPerOutput",count).put("outputs",15).put("comparedBytes",comparedBytes).put("maximumSliceBytes",2097152).put("proof","Arrays.equals on all logical Float64 bytes, including NaN payload and signedzero; no hash-only parity"));correctionCase++;nextCorrection();return;}JSONObject binding=bindings.getJSONObject(outputIndex);String id=binding.getString("id"),output=binding.getString("output");int size=Math.min(262144,count-offset);byte[] actual=source.indicatorBytes(id,output,offset,size),expected=reference.indicatorBytes(id,output,offset,size);if(!Arrays.equals(actual,expected)){int first=0;while(first<Math.min(actual.length,expected.length)&&actual[first]==expected[first])first++;mismatch=new JSONObject().put("indicator",id).put("output",output).put("correctionCase",correctionCase).put("offset",offset).put("firstDifferentByte",first).put("actualLength",actual.length).put("expectedLength",expected.length);throw new AssertionError("Large Float64 bytes differ "+id+":"+output);}comparedBytes+=actual.length;offset+=size;if(offset==count){offset=0;outputIndex++;}handler.post(this::compareChunk);}catch(Throwable error){finish(error);}}
        void invalid()throws JSONException {JSONObject event=correction(count/2);event.getJSONObject("bar").put("high",-1);active=source.applyDataEventAsync(event,new AsterEngine.AsyncOptions(120000,4096),listener(result->{try{check(result.status.equals("failed"),"Large invalid OHLC reports failed");same(snapshot(source),before,"Large failed correction preserves source");cancelBefore();}catch(Throwable error){finish(error);}}));}
        void cancelBefore()throws JSONException {active=source.applyDataEventAsync(correction(0),new AsterEngine.AsyncOptions(120000,4096),listener(result->{try{check(result.status.equals("cancelled"),"Large cancellation before capture");same(snapshot(source),before,"Large early cancellation preserves source");cancelCapture();}catch(Throwable error){finish(error);}}));active.cancel();}
        void cancelCapture()throws JSONException {final boolean[] requested={false};active=source.applyDataEventAsync(correction(0),new AsterEngine.AsyncOptions(120000,4096),new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress progress){if(progress.phase.equals("capture")&&!requested[0]){requested[0]=true;active.cancel();}}@Override public void onComplete(AsterEngine.AsyncResult result){if(finished)return;try{jobs.put(result.toJSON());active=null;check(requested[0]&&result.status.equals("cancelled"),"Large cancellation after a bounded typed copy");same(snapshot(source),before,"Large mid-copy cancellation preserves source");stale();}catch(Throwable error){finish(error);}}});}
        void stale()throws JSONException {active=source.applyDataEventAsync(correction(0),new AsterEngine.AsyncOptions(120000,4096),listener(result->{try{check(result.status.equals("stale"),"Large source mutation rejects captured request");same(snapshot(source),before,"Large stale result preserves newer source");timeout();}catch(Throwable error){finish(error);}}));JSONObject change=correction(count-1);change.getJSONObject("bar").put("close",1001);source.applyDataEvent(change);source.scene(1200,700);before=snapshot(source);}
        void timeout()throws JSONException {active=source.applyDataEventAsync(correction(0),new AsterEngine.AsyncOptions(1,1),listener(result->{try{check(result.status.equals("timedOut"),"Large request timeout");same(snapshot(source),before,"Large timeout preserves source");quota();}catch(Throwable error){finish(error);}}));}
        void quota()throws JSONException {active=source.prepareSeededAsync(AsterColumns.MAX_BARS,42,200,new AsterEngine.AsyncOptions(120000,4096),listener(result->{try{check(result.status.equals("failed")&&result.error!=null&&String.valueOf(result.error.getMessage()).contains("output budget"),"Target15-output capacity quota rejects4m preparation before bulk allocation");same(snapshot(source),before,"Target quota failure preserves1m source");boolean rejected=false;try{AsterColumns.copyOf(new double[2],new double[1],new double[2],new double[2],new double[2],new double[2]);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Owned input unequal shape rejected on calling thread");check(source.runtimeMetrics().getLong("processLiveNativeHandles")==2,"Large terminal paths leave only source and reference handles");finish(null);}catch(Throwable error){finish(error);}}));}
        void finish(Throwable error){if(finished)return;finished=true;handler.removeCallbacksAndMessages(null);if(active!=null){active.cancel();active=null;}if(reference!=null){reference.close();reference=null;}try{JSONObject report=new JSONObject().put("version","0.2.4").put("count",count).put("seed",42).put("indicators",new JSONArray(PrepareVerification.NAMES)).put("outputs",15).put("passed",error==null?checks.length():0).put("checks",checks).put("jobs",jobs).put("fullByteParity",cases).put("elapsedMs",(System.nanoTime()-started)/1e6).put("scope","Correctness fixture; source/reference setup, synchronous corrections, byte copies and full diagnostic hashes are outside performance measurements. Sequential first/middle/tail cases reuse a single seeded source and synchronous reference. At most two2MiB Java comparison slices are retained; no1m JSON numeric arrays. Full indicator bytes, layout/state/drawing and raw tail compared; diagnostic pair hashes are secondary.").put("physicalDevice",false);if(error!=null)report.put("failed",true).put("error",error.toString());if(mismatch!=null)report.put("mismatch",mismatch);completion.accept(report);}catch(JSONException reportError){throw new IllegalStateException(reportError);}}
    }
}
